posts.body:
@LaCipolla
I guess the plugin you have are trying to open the actual game on steam...(which is a good thing! It means greenworks in loaded.) maybe you can try changing the parameter? The plugin you are using tried to wrap everything in its own functions which also make it hard to read through thousands of lines.
Maybe you can try SeaPhoenix's or just copy sample code from greenworks site, achievement getting is only a few lines of code.
This is my lazy code used in my game. Just save them as plugin and call ActiveAchievement('name')
By the way I'm using nw.js 0.86, but I guess nothing big has been changed.
Spoiler:
code
JavaScript:
var greenworks = null;
try{
  greenworks = require('./greenworks'); //path to your greenworks.js
  greenworks.init();
}catch(ex){
  console.log(ex);
  greenworks = null;
};

function ActiveAchievement(achievement, success_callback, error_callback){
  try{
    success_callback = success_callback||function(){};
    error_callback = error_callback||function(){};
    greenworks.activateAchievement(achievement, success_callback, error_callback);
  }catch(ex){
    console.log('failed to active achievement: ', achievement);
    console.log(ex);
  }
}
